B.b1t=new A.bs("prophets","Stories of the Prophets","Peace be upon them all")
B.b1O=new A.bs("women","Women of Islam","The hearts that carried the light")
B.b1c=new A.bs("seerah","The Seerah","The life of the Prophet \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645")
